import fs from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import { spawn } from 'node:child_process';
import { DatabaseSync } from 'node:sqlite';
import electron from 'electron';
import sharp from 'sharp';
import { createHash } from 'node:crypto';

// Only a synthetic fixture generated by benchmark:data-layer is accepted.
const count = process.argv.includes('--stress-20000') ? 20000 : 5000;
const source = path.resolve(
  process.argv.slice(2).find((value) => !value.startsWith('--')) ||
    '.codex-runs/012/benchmark-fixtures/fixture-5000',
);
const manifest = JSON.parse(await fs.readFile(path.join(source, 'fixture.json'), 'utf8'));
if (manifest.kind !== 'synthetic-data-layer' || manifest.count !== 5000)
  throw Error('Expected a synthetic 5000-image data-layer fixture');
const root = await fs.mkdtemp(path.join(os.tmpdir(), 'nai-acceptance-'));
const output = path.resolve('.codex-runs/library-benchmark', ...(count === 5000 ? [] : ['20000']));
try {
  await fs.mkdir(output, { recursive: true });
  await fs.mkdir(path.join(root, 'userData/data'), { recursive: true });
  await fs.mkdir(path.join(root, 'userData/assets'), { recursive: true });
  await fs.writeFile(path.join(root, 'owner'), 'verify:app');
  await fs.writeFile(
    path.join(root, 'run.json'),
    JSON.stringify({ output, libraryBenchmark: true, count }),
  );
  const target = path.join(root, 'userData/data/studio.sqlite');
  await fs.copyFile(path.join(source, 'studio.sqlite'), target);
  const images = (await fs.readdir('demo/promo-v090/final')).filter((name) =>
    name.endsWith('.png'),
  );
  const media = [];
  for (let i = 0; i < images.length; i++) {
    const image = path.resolve('demo/promo-v090/final', images[i]);
    const thumbnail = path.join(root, 'userData/assets', `thumb-${i}.webp`);
    await sharp(image).resize({ width: 384 }).webp({ quality: 80 }).toFile(thumbnail);
    media.push({
      image,
      thumbnail,
      hash: createHash('sha256')
        .update(await fs.readFile(image))
        .digest('hex'),
    });
  }
  const raw = new DatabaseSync(target);
  try {
    const rows = raw.prepare('SELECT id, name FROM projects ORDER BY id').all();
    if (rows.length !== 5000 || rows.some((row) => !row.name.startsWith('Synthetic ')))
      throw Error('The fixture must contain exactly 5000 synthetic projects');
    raw.exec('BEGIN');
    const update = raw.prepare(
      'UPDATE projects SET image_path=?, thumbnail_path=?, content_hash=? WHERE id=?',
    );
    rows.forEach((row, index) =>
      update.run(
        media[index % media.length].image,
        media[index % media.length].thumbnail,
        media[index % media.length].hash,
        row.id,
      ),
    );
    raw.exec('UPDATE generation_metadata SET width=832, height=1216; COMMIT');
    if (count === 20000) {
      // Expand only the temporary synthetic copy, including all real tag/metadata payloads.
      for (let copy = 1; copy < 4; copy++) {
        raw.exec('BEGIN');
        for (const table of ['projects', 'prompt_tags', 'generation_metadata']) {
          const columns = raw
            .prepare(`PRAGMA table_info("${table}")`)
            .all()
            .map((row) => row.name);
          const values = columns.map((column) =>
            ['id', 'project_id'].includes(column)
              ? `"${column}" || '-copy-${copy}'`
              : `"${column}"`,
          );
          const idColumn = table === 'projects' ? 'id' : 'project_id';
          raw.exec(
            `INSERT INTO "${table}" (${columns.map((c) => `"${c}"`).join(',')}) SELECT ${values.join(',')} FROM "${table}" WHERE "${idColumn}" LIKE 'image-%' AND "${idColumn}" NOT LIKE '%-copy-%'`,
          );
        }
        raw.exec('COMMIT');
      }
    }
  } finally {
    raw.close();
  }
  const env = { ...process.env };
  delete env.ELECTRON_RUN_AS_NODE;
  delete env.NOVELAI_DEV_URL;
  await new Promise((resolve, reject) => {
    const child = spawn(electron, ['.', `--verify-app=${root}`], {
      env,
      windowsHide: true,
      stdio: 'inherit',
      shell: false,
    });
    const timer = setTimeout(() => {
      child.kill();
      reject(Error('Library benchmark timed out'));
    }, 300000);
    child.once('error', (error) => {
      clearTimeout(timer);
      reject(error);
    });
    child.once('exit', (code) => {
      clearTimeout(timer);
      code === 0 ? resolve() : reject(Error(`Benchmark exit ${code}`));
    });
  });
  console.log(await fs.readFile(path.join(output, 'metrics.json'), 'utf8'));
} finally {
  if (
    path.dirname(root) !== path.resolve(os.tmpdir()) ||
    !path.basename(root).startsWith('nai-acceptance-')
  )
    throw Error('Unsafe benchmark cleanup');
  await fs.rm(root, { recursive: true, force: true, maxRetries: 20, retryDelay: 250 });
}
